def get_trending_datasets(limit=20, offset=0, sort_by='trendingScore', order='desc', author=None, tags=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0001000" if __import__("os").path.isdir("./environment_mix/0001000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate pagination
    if limit is None:
        limit = 20
    if offset is None:
        offset = 0
    if not isinstance(limit, int) or limit < 1:
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1", field="limit")
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0", field="offset")

    allowed_sort = {"trendingScore", "downloads", "likes", "createdAt", "lastModified"}
    if sort_by is None:
        sort_by = "trendingScore"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort:
        return _err("VALIDATION_ERROR", "Unsupported sort_by value", field="sort_by", allowed=sorted(allowed_sort))

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in {"asc", "desc"}:
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'", field="order", allowed=["asc", "desc"])

    if author is not None and (not isinstance(author, str) or not author.strip()):
        return _err("VALIDATION_ERROR", "author must be a non-empty string when provided", field="author")

    if tags is not None:
        if not isinstance(tags, list):
            return _err("VALIDATION_ERROR", "tags must be an array of strings when provided", field="tags")
        for i, t in enumerate(tags):
            if not isinstance(t, str) or not t.strip():
                return _err("VALIDATION_ERROR", "tags must contain only non-empty strings", field="tags", index=i)

    rows = _load("trending_datasets.json")
    if not isinstance(rows, list):
        rows = []

    # Filters
    if author is not None:
        rows = [r for r in rows if isinstance(r, dict) and r.get("author") == author]
    if tags:
        req = set(tags)
        def _has_all_tags(r):
            rt = r.get("tags", [])
            if not isinstance(rt, list):
                return False
            return req.issubset(set([x for x in rt if isinstance(x, str)]))
        rows = [r for r in rows if isinstance(r, dict) and _has_all_tags(r)]

    # Sorting helpers
    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    reverse = (order == "desc")

    if sort_by in {"createdAt", "lastModified"}:
        def _sort_key(r):
            dt = _parse_dt(r.get(sort_by))
            # Put missing/unparseable dates at the end regardless of direction
            missing = (dt is None)
            val = dt.timestamp() if dt is not None else 0.0
            return (missing, val)
    else:
        def _sort_key(r):
            v = r.get(sort_by)
            if isinstance(v, bool):
                v = int(v)
            if isinstance(v, (int, float)):
                return v
            return -10**30 if reverse else 10**30

    try:
        rows_sorted = sorted([r for r in rows if isinstance(r, dict)], key=_sort_key, reverse=reverse)
    except Exception:
        # If sorting fails due to mixed incomparable keys, fall back to stable order
        rows_sorted = [r for r in rows if isinstance(r, dict)]

    total = len(rows_sorted)
    start = offset
    end = offset + limit
    page = rows_sorted[start:end]
    has_more = end < total
    next_cursor = str(end) if has_more else None

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "order": order,
        },
    }

