def get_dataset_by_id(dataset_id, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0001000" if __import__("os").path.isdir("./environment_mix/0001000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if dataset_id is None or not isinstance(dataset_id, str) or not dataset_id.strip():
        return _err("VALIDATION_ERROR", "dataset_id must be a non-empty string", field="dataset_id")

    rows = _load("trending_datasets.json")
    if not isinstance(rows, list):
        rows = []

    target = dataset_id.strip()
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("_id") == target or r.get("id") == target:
            return {"data": r}

    return _err("NOT_FOUND", "Dataset not found", dataset_id=target)

